    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    $stmt = $pdo->prepare("INSERT INTO ashram_tracks (
        track_key, title_hindi, title_english, subtitle_hindi, duration_text,
